<script setup lang="ts">
definePageMeta({ layout: 'admin' })
const authStore = useAuthStore(); if (authStore.user?.role !== 'ADMIN') throw createError({ statusCode: 403, statusMessage: 'Forbidden' })
const service = useLogsService(); const logs=ref<any[]>([]); const isLoading=ref(false); const errorMessage=ref(''); const selected=ref<any|null>(null)
const filters=reactive({ entity:'', entityId:'', action:'', user:'', startDate:'', endDate:'' })
const sanitize = (text: string) => text.replace(/(token|password|secret)\s*[:=]\s*[^\s,;]+/gi, '$1: [REDACTED]')
const load=async()=>{ isLoading.value=true; try{ const data=await service.list(filters as any); logs.value=data.map((log)=>({ ...log, details:sanitize(log.details||'') })) }catch(e){ errorMessage.value=getFriendlyErrorMessage(e) }finally{ isLoading.value=false } }
onMounted(load)
</script>
<template><div class="space-y-4"><h2 class="text-2xl font-semibold">Logs administrativos</h2><BaseCard><div class="grid gap-3 md:grid-cols-3"><BaseInput v-model="filters.entity" label="Entidade"/><BaseInput v-model="filters.entityId" label="ID da entidade"/><BaseInput v-model="filters.action" label="Ação"/><BaseInput v-model="filters.user" label="Usuário"/><BaseInput v-model="filters.startDate" label="Período inicial" type="date"/><BaseInput v-model="filters.endDate" label="Período final" type="date"/></div><div class="mt-3"><BaseButton :loading="isLoading" label="Filtrar" @click="load"/></div></BaseCard><BaseAlert v-if="errorMessage" type="error" :message="errorMessage"/><div v-else-if="isLoading" class="flex items-center gap-2"><BaseLoading/> Loading logs...</div><BaseTable v-else-if="logs.length"><thead><tr><th class="p-2">Data/hora</th><th>Entidade</th><th>Ação</th><th>Usuário</th><th>Origem</th><th>Resumo</th><th>Detalhes</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id" class="border-b"><td class="p-2">{{log.dateTime}}</td><td>{{log.entity}}</td><td>{{log.action}}</td><td>{{log.user}}</td><td>{{log.origin}}</td><td>{{log.summary}}</td><td><BaseButton variant="secondary" label="Abrir" @click="selected = log"/></td></tr></tbody></BaseTable><EmptyState v-else title="Sem logs" description="Nenhum log encontrado para os filtros."/><BaseModal :open="Boolean(selected)" title="Detalhes do log" @close="selected = null"><pre class="max-h-96 overflow-auto whitespace-pre-wrap text-xs">{{ selected?.details }}</pre></BaseModal></div></template>
